CREATE COLUMN TABLE "TEST_AP"."OCMT" ("CompetId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(15) NOT NULL , "ThreatLevl" SMALLINT CS_INT DEFAULT 1, "Memo" NVARCHAR(50), "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("CompetId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCMT_NAME" ON "TEST_AP"."OCMT" ( "Name" ASC )